import type { Side } from "./twin";

export type LongPress = { target: HTMLElement; tip: string; side: Side; x: number; y: number };
export const LONG_PRESS_MS = 400;
const SLOP_PX = 10;
const SWALLOW_MS = 700;
const sideOf = (el: HTMLElement): Side => {
  const marked = el.closest<HTMLElement>("[data-side]")?.dataset.side;
  if (marked === "far" || marked === "near") return marked;
  return el.closest("[data-testid='seats-far'], [data-testid='rail-far']") ? "far" : "near";
};
type Hold = { target: HTMLElement; x: number; y: number; timer: number | null; fired: boolean };
type Suppression = { target: HTMLElement; until: number };

export const installPress = (
  root: Document | HTMLElement = document,
  options: { ms?: number; onLong?: (press: LongPress) => void } = {},
): (() => void) => {
  const doc = root instanceof Document ? root : root.ownerDocument;
  const view = doc.defaultView!;
  const holds = new Map<number, Hold>();
  const suppressed = new Map<number, Suppression>();
  const eligible = (target: HTMLElement): boolean => target.isConnected && root.contains(target)
    && !target.closest(':disabled, [aria-disabled="true"], [inert]');
