    suppressed.delete(pointer.pointerId); // a subsequent intentional tap must work
    const target = pointer.target instanceof Element ? pointer.target.closest<HTMLElement>("[data-tip]") : null;
    if (!target || !eligible(target)) return;
    const hold: Hold = { target, x: pointer.clientX, y: pointer.clientY, timer: null, fired: false };
    holds.set(pointer.pointerId, hold);
    target.classList.add("is-holding");
